    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address attacker) public payable {
        require(attacker != address(this));
        address origOwner = c.owner();
        address caller = attacker == origOwner ? address(0xdead) : attacker;
        c.setOwner(newOwner);
        require(c.owner() == newOwner);
        bool reverted;
        // This call uses an alias-free direct external call; owner is now newOwner, so caller (not newOwner) should be rejected
        try c.setOwner(caller) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == newOwner);
    }
}

