        require(newOwner != address(0));

        address currentOwnerBefore = c.owner();
        bool callerIsOwner = (caller == currentOwnerBefore);

        // Perform the state-changing call as its own top-level statement.
        // Since the checker calls this test contract, msg.sender here is the test contract,
        // so we can only exercise the owner path when this test contract is the owner.
        bool callSucceeded;
        bool callReverted;
        try c.setOwner(newOwner) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
            callReverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: setOwner succeeds exactly when the caller has owner authority,
        // and on success the owner is updated; on revert the owner is unchanged.
        assert(
            (callerIsOwner && callSucceeded && ownerAfter == newOwner) ||
            (!callerIsOwner && callReverted && ownerAfter == currentOwnerBefore)
        );
    }

    receive() external payable {}
}

